// Check exit code and format result
const stdout = $json.stdout || '';
const stderr = $json.stderr || '';
const exitCode = $json.exitCode || 0;

if (exitCode !== 0) {
  // Don't throw — let it pass through to Telegram alert
  return [{ json: { success: false, error: stderr, tap: 'tap-google-ads' } }];
}

// Parse counts from singer_to_analytics output
const match = (stdout + stderr).match(/Done: (.+)/);
return [{ json: { success: true, output: match?.[1] || 'ok', tap: 'tap-google-ads' } }];
